import React, { useRef, useEffect, useState, useMemo } from 'react';
import { FormState, ContentType, QuestionType, QuestionDifficulty, ROWCLessonEntry } from '../types.ts';
import { GRADES, CONTENT_TYPES, ASSESSMENT_QUESTION_TYPES, SUBJECTS_BY_GRADE } from '../constants.tsx';
import { getCurriculumByTerm } from '../curriculumData.ts';
import { parseDocument } from '../services/documentParser.ts';
import { CustomSelect } from './CustomSelect.tsx';
import { ContentTypeIcon } from './ContentTypeIcon.tsx';
import { Tooltip } from './Tooltip.tsx';

interface GeneratorFormProps {
  formState: FormState;
  setFormState: React.Dispatch<React.SetStateAction<FormState>>;
  onSubmit: (e: React.FormEvent) => void;
  isLoading: boolean;
  onStartNew: () => void;
}

const MultiSelectDropdown: React.FC<{
  options: string[];
  selectedOptions: string[];
  onChange: (selected: string[]) => void;
  placeholder: string;
  disabled?: boolean;
}> = ({ options, selectedOptions, onChange, placeholder, disabled = false }) => {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const handleOptionToggle = (option: string) => {
    const newSelection = selectedOptions.includes(option)
      ? selectedOptions.filter((item) => item !== option)
      : [...selectedOptions, option];
    onChange(newSelection.sort());
  };

  const displayText = selectedOptions.length > 0 ? selectedOptions.join(', ') : placeholder;

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        type="button"
        onClick={() => !disabled && setIsOpen(!isOpen)}
        disabled={disabled}
        className="block w-full text-left shadow-sm sm:text-sm bg-white dark:bg-slate-100 border-gray-300 dark:border-slate-300 text-black rounded-md p-2 truncate disabled:bg-gray-100 dark:disabled:bg-slate-100 disabled:cursor-not-allowed"
      >
        <span className="flex justify-between items-center">
          <span className="truncate pr-2">{displayText}</span>
           <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-gray-500" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
            </svg>
        </span>
      </button>
      {isOpen && (
        <div className="absolute z-20 mt-1 w-full bg-white dark:bg-slate-700 shadow-lg border border-gray-300 dark:border-slate-600 rounded-md max-h-60 overflow-auto">
          {options.map((option) => (
            <label key={option} className="flex items-center space-x-3 cursor-pointer p-2 hover:bg-gray-100 dark:hover:bg-slate-600 border-b border-gray-100 dark:border-slate-600 last:border-b-0">
              <input
                type="checkbox"
                className="h-4 w-4 rounded border-gray-300 dark:border-slate-500 text-emerald-600 focus:ring-emerald-500"
                checked={selectedOptions.includes(option)}
                onChange={() => handleOptionToggle(option)}
              />
              <span className="text-sm text-gray-700 dark:text-white">{option}</span>
            </label>
          ))}
        </div>
      )}
    </div>
  );
};

const StrandItem: React.FC<{
    strand: string;
    subStrands: string[];
    selection: string[] | undefined;
    onStrandChange: (strand: string, checked: boolean) => void;
    onSubStrandChange: (strand: string, subStrand: string, checked: boolean) => void;
}> = ({ strand, subStrands, selection, onStrandChange, onSubStrandChange }) => {
    const [isExpanded, setIsExpanded] = useState(false);
    const strandCheckboxRef = useRef<HTMLInputElement>(null);

    const isFullStrandSelected = selection !== undefined && selection.length === 0;
    const selectedSubStrandCount = Array.isArray(selection) ? selection.length : 0;
    const totalSubStrands = Array.isArray(subStrands) ? subStrands.length : 0;

    const areAllSubStrandsSelected = isFullStrandSelected || (selectedSubStrandCount > 0 && selectedSubStrandCount === totalSubStrands);
    const isPartiallySelected = !isFullStrandSelected && selectedSubStrandCount > 0 && selectedSubStrandCount < totalSubStrands;

    useEffect(() => {
        if (strandCheckboxRef.current) {
            strandCheckboxRef.current.indeterminate = isPartiallySelected;
        }
    }, [isPartiallySelected]);

    return (
        <div className="py-2">
            <div className="flex items-center justify-between">
                <label className="flex items-center space-x-3 cursor-pointer p-2 flex-grow hover:bg-gray-100 dark:hover:bg-slate-700 rounded-md">
                    <input
                        ref={strandCheckboxRef}
                        type="checkbox"
                        className="h-4 w-4 rounded border-gray-300 dark:border-slate-500 text-emerald-600 focus:ring-emerald-500 dark:bg-slate-600"
                        checked={areAllSubStrandsSelected}
                        onChange={(e) => onStrandChange(strand, e.target.checked)}
                    />
                    <span className="font-semibold text-gray-800 dark:text-white">{strand}</span>
                </label>
                {totalSubStrands > 0 && (
                    <button
                        type="button"
                        onClick={() => setIsExpanded(!isExpanded)}
                        className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-slate-700 text-gray-500 dark:text-white"
                        aria-expanded={isExpanded}
                        aria-label={isExpanded ? "Collapse sub-strands" : "Expand sub-strands"}
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-5 w-5 transition-transform ${isExpanded ? 'rotate-180' : ''}`} viewBox="0 0 20 20" fill="currentColor">
                            <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                        </svg>
                    </button>
                )}
            </div>
            {isExpanded && totalSubStrands > 0 && (
                <div className="pl-8 pt-1 space-y-1 border-l-2 border-gray-200 dark:border-slate-700 ml-4">
                    {subStrands.map(subStrand => {
                         const isChecked = isFullStrandSelected || (selection?.includes(subStrand) ?? false);
                         return (
                            <label key={subStrand} className="flex items-center space-x-3 cursor-pointer p-2 hover:bg-gray-100 dark:hover:bg-slate-700/50 rounded-md">
                                <input
                                    type="checkbox"
                                    className="h-4 w-4 rounded border-gray-300 dark:border-slate-500 text-emerald-600 focus:ring-emerald-500 dark:bg-slate-600"
                                    checked={isChecked}
                                    onChange={(e) => onSubStrandChange(strand, subStrand, e.target.checked)}
                                />
                                <span className="text-sm text-gray-600 dark:text-white">{subStrand}</span>
                            </label>
                         );
                    })}
                </div>
            )}
        </div>
    );
};


export const GeneratorForm: React.FC<GeneratorFormProps> = ({ formState, setFormState, onSubmit, isLoading, onStartNew }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const markingSchemeFileInputRef = useRef<HTMLInputElement>(null);

  const [fileError, setFileError] = useState<string | null>(null);
  const [fileInfo, setFileInfo] = useState<string | null>(null);
  const [isProcessingFile, setIsProcessingFile] = useState(false);

  const [markingSchemeFileError, setMarkingSchemeFileError] = useState<string | null>(null);
  const [markingSchemeFileInfo, setMarkingSchemeFileInfo] = useState<string | null>(null);
  const [isProcessingMarkingScheme, setIsProcessingMarkingScheme] = useState(false);

  const [activeSection, setActiveSection] = useState<'topic' | 'assessment' | 'customization'>('topic');
  const [errors, setErrors] = useState<Record<string, string>>({});

  const [subjectOptions, setSubjectOptions] = useState<string[]>(SUBJECTS_BY_GRADE[formState.grade] || []);

  const contentTypeOptions = useMemo(() => {
    return CONTENT_TYPES.map(c => ({
        value: c,
        label: c,
        icon: <ContentTypeIcon type={c} className="h-5 w-5" />
    }));
  }, []);

  // Dynamically load curriculum based on Term selection
  const subjectCurriculum = useMemo(() => {
      const selectedTerms = formState.terms && formState.terms.length > 0 ? formState.terms : ['Term 1', 'Term 2', 'Term 3'];
      return getCurriculumByTerm(formState.grade, formState.subject, selectedTerms);
  }, [formState.grade, formState.subject, formState.terms]);

  const isRowcType = formState.contentType === ContentType.RecordOfWorkCovered;
  const isSchemeOfWorkType = formState.contentType === ContentType.SchemeOfWork;
  const isLessonPlan = formState.contentType === ContentType.LessonPlan;
  const isAssessmentType = [ContentType.Assessment, ContentType.Quiz, ContentType.TopicExam, ContentType.TermExam].includes(formState.contentType);

  // Enable curriculum accordion for SOW, Plans, and Notes
  const enableCurriculumAccordion = !isRowcType;

  // Enforce Strict Curriculum Adherence for Schemes of Work
  useEffect(() => {
    if (isSchemeOfWorkType && !formState.strictCurriculumAdherence) {
      setFormState(prev => ({ ...prev, strictCurriculumAdherence: true }));
    }
  }, [isSchemeOfWorkType, formState.strictCurriculumAdherence, setFormState]);

  // Effect to set professional template for lesson plans
  useEffect(() => {
    if (formState.contentType === ContentType.LessonPlan) {
      setFormState(prev => ({
        ...prev,
        additionalInstructions: 'Template: Structured & Professional (Best for Portfolios)'
      }));
    }
  }, [formState.contentType, setFormState]);

  // Effect to set default question counts when switching to Assessment types
  useEffect(() => {
    if (isAssessmentType) {
         const currentTotal = Object.values(formState.questionCounts).reduce((a: number, b: number | undefined) => a + (b || 0), 0);

         if (currentTotal === 0) {
             setFormState(prev => ({
                 ...prev,
                 distributionMode: 'manual', 
                 totalQuestions: 25,
                 questionCounts: {
                     [QuestionType.MultipleChoice]: 20,
                     [QuestionType.ShortAnswer]: 5,
                     [QuestionType.TrueFalse]: 0,
                     [QuestionType.Essay]: 0,
                     [QuestionType.Discussion]: 0
                 },
                 questionMarks: {
                     [QuestionType.MultipleChoice]: 1,
                     [QuestionType.ShortAnswer]: 2,
                     [QuestionType.TrueFalse]: 1,
                     [QuestionType.Essay]: 10,
                     [QuestionType.Discussion]: 5
                 }
             }));
         }
    }
  }, [formState.contentType, isAssessmentType, setFormState]);

  useEffect(() => {
    const newSubjectOptions = SUBJECTS_BY_GRADE[formState.grade] || [];
    setSubjectOptions(newSubjectOptions);

    if (!newSubjectOptions.includes(formState.subject)) {
      setFormState(prev => ({
        ...prev,
        subject: newSubjectOptions[0] || '',
        multiSelectTopics: {},
        topic: '',
      }));
    } else {
        setFormState(prev => ({
            ...prev,
            multiSelectTopics: {},
            topic: prev.topicInputMode === 'curriculum' ? '' : prev.topic
        }));
    }
  }, [formState.grade, formState.subject, setFormState]);

  useEffect(() => {
    if (formState.topicInputMode === 'manual' || isRowcType) return;

    const { multiSelectTopics } = formState;
    const hasMultiSelectTopics = multiSelectTopics && Object.keys(multiSelectTopics).length > 0;

    if (hasMultiSelectTopics && subjectCurriculum) {
        const topicParts = Object.entries(multiSelectTopics).map(([strand, subStrands]) => {
            if (!Array.isArray(subStrands)) return null;
            if (subStrands.length === 0) {
                const allSubStrands = subjectCurriculum[strand] || [];
                if (allSubStrands.length > 0) {
                     return `${strand} (covering: ${allSubStrands.join(', ')})`;
                }
                return strand;
            } else {
                return `${strand} (specifically covering: ${subStrands.join(', ')})`;
            }
        });

        const topicList = topicParts.filter(Boolean).map((part, index) => `${index + 1}. ${part}`).join('\n');
        const fullTopic = `Content covering the following curriculum topics:\n${topicList}`;

        setFormState(prev => {
            if (prev.topic !== fullTopic) {
                return { ...prev, topic: fullTopic };
            }
            return prev;
        });

    } else {
        setFormState(prev => {
            if (prev.topic !== '') {
                return { ...prev, topic: '' }
            }
            return prev;
        });
    }
}, [formState.topicInputMode, formState.multiSelectTopics, formState.grade, formState.subject, isRowcType, subjectCurriculum, setFormState]);


  useEffect(() => {
    if (!formState.documentFile && fileInputRef.current) {
        fileInputRef.current.value = '';
    }
    if (!formState.markingSchemeFile && markingSchemeFileInputRef.current) {
        markingSchemeFileInputRef.current.value = '';
    }
  }, [formState.documentFile, formState.markingSchemeFile]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target;
    const isCheckbox = type === 'checkbox';
    const checked = isCheckbox ? (e.target as HTMLInputElement).checked : undefined;

    if (name in formState.questionCounts) {
        const parsedValue = parseInt(value, 10);
        const finalValue = isNaN(parsedValue) || parsedValue < 0 ? 0 : parsedValue;

        setFormState(prev => ({
        ...prev,
        questionCounts: { ...prev.questionCounts, [name]: finalValue }
      }));
    } else {
      setFormState(prev => ({ ...prev, [name]: isCheckbox ? checked : value }));
    }
    if (errors[name]) {
        setErrors(prev => {
            const updatedErrors = { ...prev };
            delete updatedErrors[name];
            return updatedErrors;
        });
    }
  };

  const handleMarksChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const { name, value } = e.target;
      const type = name.replace('mark_', '') as QuestionType;
      const parsedValue = parseInt(value, 10);
      const finalValue = isNaN(parsedValue) || parsedValue < 1 ? 1 : parsedValue;

      setFormState(prev => ({
          ...prev,
          questionMarks: { ...prev.questionMarks, [type]: finalValue }
      }));
  };

  const handleTermSelectChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      const value = e.target.value as 'Term 1' | 'Term 2' | 'Term 3' | '';
      setFormState(prev => ({
          ...prev,
          term: value as any,
          terms: value ? [value as any] : [],
          multiSelectTopics: {}
      }));
       if (errors.terms) {
            setErrors(prev => {
                const updatedErrors = {...prev};
                delete updatedErrors.terms;
                return updatedErrors;
            });
        }
  };

  const handleAddLesson = () => {
    if (formState.week && formState.lessonNumber) {
      setFormState(prev => ({
        ...prev,
        selectedLessons: [...(prev.selectedLessons || []), { week: prev.week!, lesson: prev.lessonNumber! }]
      }));
    }
  };

  const handleRemoveLesson = (index: number) => {
    setFormState(prev => ({
      ...prev,
      selectedLessons: prev.selectedLessons?.filter((_, i) => i !== index)
    }));
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>, fileType: 'documentFile' | 'markingSchemeFile') => {
    const file = e.target.files?.[0];
    const isDoc = fileType === 'documentFile';
    const setError = isDoc ? setFileError : setMarkingSchemeFileError;
    const setInfo = isDoc ? setFileInfo : setMarkingSchemeFileInfo;
    const setProcessing = isDoc ? setIsProcessingFile : setIsProcessingMarkingScheme;

    setFormState(prev => ({
      ...prev,
      [isDoc ? 'documentFile' : 'markingSchemeFile']: undefined,
      [isDoc ? 'documentText' : 'markingSchemeText']: '',
      [isDoc ? 'documentImageBase64' : 'markingSchemeImageBase64']: undefined,
      [isDoc ? 'documentImageMimeType' : 'markingSchemeImageMimeType']: undefined,
    }));
    setError(null);
    setInfo(null);
    e.target.value = ''; 

    if (!file) return;

    const MAX_FILE_SIZE_MB = 10;
    if (file.size > MAX_FILE_SIZE_MB * 1024 * 1024) {
      setError(`File is too large. Max size is ${MAX_FILE_SIZE_MB}MB.`);
      return;
    }

    const allowedExtensions = ['.txt', '.pdf', '.doc', '.docx', '.jpg', '.jpeg', '.png'];
    const fileExtension = `.${file.name.split('.').pop()?.toLowerCase()}`;

    if (!allowedExtensions.includes(fileExtension)) {
      setError(`Unsupported file. Please upload: ${allowedExtensions.join(', ')}`);
      return;
    }

    setFormState(prev => ({ ...prev, [isDoc ? 'documentFile' : 'markingSchemeFile']: file }));
    setProcessing(true); 

    try {
        if (['.jpg', '.jpeg', '.png'].includes(fileExtension)) {
            const reader = new FileReader();
            reader.onload = (event) => {
                const dataUrl = event.target?.result as string;
                const base64 = dataUrl.split(',')[1];
                setFormState(prev => ({ 
                    ...prev, 
                    [isDoc ? 'documentImageBase64' : 'markingSchemeImageBase64']: base64, 
                    [isDoc ? 'documentImageMimeType' : 'markingSchemeImageMimeType']: file.type,
                    ...(isDoc ? { topicInputMode: 'manual', topic: '' } : {})
                }));
                setProcessing(false);
            };
            reader.readAsDataURL(file);

        } else {
            const textContent = await parseDocument(file);

            if (!textContent || textContent.trim() === '') {
                 throw new Error("No text content could be extracted from the file.");
            }

            setFormState(prev => ({ 
                ...prev, 
                [isDoc ? 'documentText' : 'markingSchemeText']: textContent,
                ...(isDoc ? { topicInputMode: 'manual', topic: '' } : {})
            }));

            setInfo(`Successfully extracted ${textContent.length} characters.`);
            setProcessing(false);
        }
    } catch (err: any) {
        console.error("File processing error:", err);
        setError(err.message || "Failed to process the file.");
        setProcessing(false);
    }
  };

  const handleTotalQuestionsChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseInt(e.target.value, 10);
    setFormState(prev => ({ ...prev, totalQuestions: isNaN(val) || val < 1 ? 1 : val }));
    if (errors.totalQuestions) {
        setErrors(prev => {
            const updatedErrors = {...prev};
            delete updatedErrors.totalQuestions;
            return updatedErrors;
        });
    }
  };

    const handleROWCToggleChange = (lessonId: string, field: 'strandInputMode' | 'subStrandInputMode', value: 'curriculum' | 'manual') => {
        setFormState(prev => {
            if (!prev.rowcData || !Array.isArray(prev.rowcData.lessons)) return prev;
            const updatedLessons = prev.rowcData.lessons.map(lesson => {
                if (lesson.id === lessonId) {
                    const updatedLesson = { ...lesson, [field]: value };
                    if (value === 'curriculum') {
                        if (field === 'strandInputMode') updatedLesson.strand = '';
                        if (field === 'subStrandInputMode') updatedLesson.subStrand = '';
                    }
                    return updatedLesson;
                }
                return lesson;
            });
            return { ...prev, rowcData: { ...prev.rowcData, lessons: updatedLessons } };
        });
    };

  const handleROWCLessonChange = (id: string, e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormState(prev => {
        if (!prev.rowcData || !Array.isArray(prev.rowcData.lessons)) return prev;
        const updatedLessons = prev.rowcData.lessons.map(lesson => {
            if (lesson.id === id) {
                const updatedLesson: ROWCLessonEntry = { ...lesson, [name as keyof ROWCLessonEntry]: value };
                if (name === 'grade') { updatedLesson.subject = ''; updatedLesson.strand = ''; updatedLesson.subStrand = ''; } 
                else if (name === 'subject') { updatedLesson.strand = ''; updatedLesson.subStrand = ''; } 
                else if (name === 'strand') { updatedLesson.subStrand = ''; }
                return updatedLesson;
            }
            return lesson;
        });
        return { ...prev, rowcData: { ...prev.rowcData, lessons: updatedLessons } };
    });
    const lessonIndex = formState.rowcData!.lessons.findIndex(l => l.id === id);
    const errorKey = `lesson_${lessonIndex}_${name}`;
    if (errors[errorKey]) {
        setErrors(prev => {
            const updatedErrors = { ...prev };
            delete updatedErrors[errorKey];
            return updatedErrors;
        });
    }
  };

  const addROWCLesson = () => {
    setFormState(prev => {
        const newLesson: ROWCLessonEntry = {
            id: `lesson_${Date.now()}`, date: '', grade: '', subject: '', term: '', strand: '', subStrand: '',
            strandInputMode: 'curriculum', subStrandInputMode: 'curriculum',
            lessonTitle: '', learningActivities: '', resources: '', assessment: '', remarks: ''
        };
        const lessons = prev.rowcData?.lessons || [];
        return { ...prev, rowcData: { ...prev.rowcData!, lessons: [...lessons, newLesson] } };
    });
  };

  const removeROWCLesson = (id: string) => {
    setFormState(prev => {
        if (!prev.rowcData) return prev;
        return { ...prev, rowcData: { ...prev.rowcData, lessons: prev.rowcData.lessons.filter(l => l.id !== id) } };
    });
  };

  const handleStrandChange = (strand: string, isChecked: boolean) => {
        setFormState(prev => {
            const updatedTopics: { [strand: string]: string[] } = { ...(prev.multiSelectTopics || {}) };
            if (isChecked) {
                updatedTopics[strand] = []; 
            } else {
                delete updatedTopics[strand];
            }
            return { ...prev, multiSelectTopics: updatedTopics };
        });
        if (errors.topic) {
            setErrors(prev => {
                const updatedErrors = {...prev};
                delete updatedErrors.topic;
                return updatedErrors;
            });
        }
    };

    const handleSubStrandChange = (strand: string, subStrand: string, isChecked: boolean) => {
        setFormState(prev => {
            const allSubStrandsForStrand = subjectCurriculum?.[strand] || [];
            const updatedTopics: { [strand: string]: string[] } = { ...(prev.multiSelectTopics || {}) };

            const currentSelection = (updatedTopics[strand]?.length === 0 && updatedTopics.hasOwnProperty(strand))
                ? allSubStrandsForStrand
                : (updatedTopics[strand] || []);

            let newSelection: string[];

            if (isChecked) {
                newSelection = [...new Set([...currentSelection, subStrand])];
            } else {
                newSelection = currentSelection.filter(ss => ss !== subStrand);
            }

            if (newSelection.length === 0) {
                delete updatedTopics[strand];
            } else if (allSubStrandsForStrand.length > 0 && newSelection.length === allSubStrandsForStrand.length) {
                updatedTopics[strand] = []; 
            } else {
                updatedTopics[strand] = newSelection.sort();
            }

            return { ...prev, multiSelectTopics: updatedTopics };
        });
    };

    const validateForm = (): boolean => {
        const newErrors: Record<string, string> = {};
        const { contentType, topic, topicInputMode, multiSelectTopics, distributionMode, totalQuestions, questionCounts, terms, rowcData, selectedLessons } = formState;

        if (!formState.grade) newErrors.grade = "Grade is required.";
        if (!formState.subject) newErrors.subject = "Subject is required.";

        const needsTopic = ![ContentType.SchemeOfWork, ContentType.TermExam, ContentType.RecordOfWorkCovered].includes(contentType);

        const hasSelectedLessons = isLessonPlan && selectedLessons && selectedLessons.length > 0;
        const hasUploadedContent = !!formState.documentText || !!formState.documentImageBase64;

        if (needsTopic && !hasUploadedContent && !hasSelectedLessons) {
            if (topicInputMode === 'manual' && (!topic || !topic.trim())) {
                newErrors.topic = 'Please enter a topic or paste content manually.';
            }
            if (topicInputMode === 'curriculum' && (!multiSelectTopics || Object.keys(multiSelectTopics).length === 0)) {
                if (formState.topic && !enableCurriculumAccordion) {
                } else if (!formState.topic || formState.topic.trim() === '') {
                     newErrors.topic = 'Please select at least one curriculum topic.';
                }
            }
        }

        if (isAssessmentType) {
            if (distributionMode === 'auto' && (!totalQuestions || totalQuestions < 1)) {
                newErrors.totalQuestions = 'Please enter a total number of questions greater than 0.';
            }
            if (distributionMode === 'manual') {
                const counts = questionCounts || {};
                let totalManualQuestions = 0;
                for (const count of Object.values(counts)) {
                    totalManualQuestions += Number(count) || 0;
                }

                if (totalManualQuestions < 1) {
                    newErrors.questionCounts = 'Please specify a count for at least one question type (Total must be > 0).';
                    setActiveSection('assessment');
                }
            }
        }

        if (isSchemeOfWorkType && (!terms || terms.length === 0)) {
            newErrors.terms = 'Please select a term for the Scheme of Work.';
        }

        if (isRowcType) {
            if (!rowcData?.weekRange.trim()) {
                newErrors.weekRange = 'Week Range is required.';
            }
             if (rowcData?.lessons && rowcData.lessons.length > 0) {
